<script setup lang="ts">
import { onMounted, onUnmounted, reactive, ref, computed, watch } from 'vue'
import { ElMessage } from 'element-plus'
import { api, type Page } from './api'
interface Option { id: string; name: string; companyId?: string; companyIds?: string[]; companies?: { companyId: string; active: boolean }[]; active?: boolean }
interface Connection { id: string; name: string; adapterType: string }
interface Job { id: string; connectionId: string; scenario: string; status: string; processed: number; applied: number; skipped: number; quarantined: number; attempts: number; errorCode: string | null; version: number; nextCursor: string | null; snapshotId: string }
interface Issue { id: string; externalKey: string; sourceRevision: string; errorCode: string }
const connections = ref<Connection[]>([]), jobs = ref<Job[]>([]), companies = ref<Option[]>([]), plants = ref<Option[]>([]), orgs = ref<Option[]>([]), suppliers = ref<Option[]>([]), busy = ref(false), createOpen = ref(false), issuesOpen = ref(false), issues = ref<Issue[]>([]), selected = ref<Job>(), page = ref(1), total = ref(0), issuePage = ref(1), issueTotal = ref(0)
const form = reactive({ name: '', companyId: '', purchasingOrgId: '', supplierId: '', plantIds: [] as string[], adapterType: 'mock', sourceSystem: 'SAP_SANDBOX', sourceClient: '', companyExternalKey: '', purchasingOrgExternalKey: '', supplierExternalKey: '' }), start = reactive({ connectionId: '', scenario: 'INITIAL' })
const externalPlants = reactive<Record<string,string>>({})
const adapters = ref<{adapterType: string; configured: boolean; writeEnabled: boolean}[]>([])
const sapScenarios: Record<string,string> = { SAP_METADATA: '验证接口元数据', SAP_READ: '读取授权采购订单', SAP_RECEIPTS: '读取授权收货及冲销' }
const availableScenarios = computed(() => connections.value.find(c => c.id === start.connectionId)?.adapterType === 'sap-odata' ? sapScenarios : scenarios)
watch(() => start.connectionId, () => { start.scenario = connections.value.find(c => c.id === start.connectionId)?.adapterType === 'sap-odata' ? 'SAP_METADATA' : 'INITIAL' })
const states: Record<string, string> = { PENDING: '排队', RUNNING: '进行中', SUCCEEDED: '完成', FAILED: '失败', QUARANTINED: '存在隔离事件' }
const scenarios: Record<string, string> = { GR_INITIAL: 'ERP 收货及 ASN 分配', GR_FAIL_ONCE: '收货分页一次故障', GR_PARTIAL_REVERSE: 'ERP 部分冲销', GR_FULL_REVERSE: 'ERP 剩余全额冲销', GR_CONFLICT: '收货来源冲突', GR_OVER: 'ERP 超收', GR_UNMATCHED: 'ERP 未知订单', CONFIRMATION: '部分确认演示（100）', INITIAL: '初始订单', UPDATE: '订单新版本', DUPLICATE: '重复事件', OUT_OF_ORDER: '乱序旧版本', CONFLICT: '同版本内容冲突', CANCEL: '取消订单', CLOSE: '关闭订单', REOPEN: '重新开启', REMOVE_LINE: '移除行项目', INVALID_MAPPING: '无效工厂映射', FAIL_ONCE: '分页读取一次故障', PERMANENT_FAIL: '分页读取持续故障' }
const mappedPlants = computed(() => plants.value.filter(p => p.companyId === form.companyId && p.active))
let timer: ReturnType<typeof setInterval> | undefined
async function run(fn: () => Promise<void>) { busy.value = true; try { await fn() } catch (e) { ElMessage.error(e instanceof Error ? e.message : '操作失败') } finally { busy.value = false } }
async function all<T>(path: string) { let p = 0; const rows: T[] = []; while (true) { const v = await api<Page<T>>(`${path}?size=100&page=${p++}`); rows.push(...v.items); if (!v.items.length || rows.length >= v.total) break } return rows }
async function load() { const v = await api<Page<Job>>(`/sync-jobs?page=${page.value - 1}&size=20`); jobs.value = v.items; total.value = v.total }
async function options() { [connections.value, companies.value, plants.value, orgs.value, suppliers.value] = await Promise.all([all<Connection>('/erp-connections'), all<Option>('/companies'), all<Option>('/plants'), all<Option>('/purchasing-organizations'), all<Option>('/suppliers')]) }
async function create() { await run(async () => { const payload = { ...form, ...(form.adapterType === 'sap-odata' ? { plantMappings: Object.fromEntries(form.plantIds.map(id => [externalPlants[id] || '', id])) } : {}) }; const c = await api<Connection>('/erp-connections', 'POST', payload); createOpen.value = false; await options(); start.connectionId = c.id; ElMessage.success('连接已建立') }) }
async function launch() { await run(async () => { await api('/sync-jobs', 'POST', { ...start, entityType: start.scenario === 'SAP_METADATA' ? 'METADATA' : start.scenario === 'SAP_RECEIPTS' || start.scenario.startsWith('GR_') ? 'GOODS_RECEIPT' : 'PURCHASE_ORDER' }); page.value = 1; await load(); ElMessage.success('同步任务已提交') }) }
async function retry(j: Job) { await run(async () => { const current = await api<Job>(`/sync-jobs/${j.id}`); await api(`/sync-jobs/${j.id}/retry`, 'POST', undefined, current.version); await load(); ElMessage.success('已从原检查点重试') }) }
async function issueList() { const v = await api<Page<Issue>>(`/sync-jobs/${selected.value!.id}/issues?page=${issuePage.value - 1}&size=20`); issues.value = v.items; issueTotal.value = v.total }
async function show(j: Job) { selected.value = await api<Job>(`/sync-jobs/${j.id}`); issuePage.value = 1; await issueList(); issuesOpen.value = true }
onMounted(() => { void run(async () => { await options(); adapters.value = await api('/erp-adapters'); await load() }); timer = setInterval(() => { if (!busy.value && jobs.value.some(j => ['PENDING', 'RUNNING'].includes(j.status))) void run(load) }, 1500) })
onUnmounted(() => { if (timer) clearInterval(timer) })
</script>
<template><section class="card table-card" v-loading="busy"><div class="toolbar"><el-select v-model="start.connectionId" aria-label="同步连接" placeholder="选择同步连接"><el-option v-for="c in connections" :key="c.id" :label="c.name" :value="c.id"/></el-select><el-select v-model="start.scenario" aria-label="同步任务类型"><el-option v-for="(label, key) in availableScenarios" :key="key" :label="label" :value="key"/></el-select><el-button type="primary" @click="launch">启动同步</el-button><el-button @click="createOpen = true">新建连接</el-button><el-button @click="run(load)">刷新任务</el-button></div><p class="muted">ERP 写入始终关闭。Mock 使用固定快照；SAP 仅扫描批准的订单和组织范围，复查变更时间。收货计划行不唯一时隔离，ASN 不计作实际收货。</p>
<el-table :data="jobs" empty-text="暂无授权同步任务"><el-table-column label="连接" min-width="180"><template #default="{ row }">{{ connections.find(c => c.id === row.connectionId)?.name }}</template></el-table-column><el-table-column label="场景" min-width="160"><template #default="{ row }">{{ sapScenarios[row.scenario] || scenarios[row.scenario] }}</template></el-table-column><el-table-column label="状态" min-width="150"><template #default="{ row }">{{ states[row.status] }}</template></el-table-column><el-table-column prop="processed" label="处理"/><el-table-column prop="applied" label="更新"/><el-table-column prop="skipped" label="跳过"/><el-table-column prop="quarantined" label="隔离"/><el-table-column prop="attempts" label="重试"/><el-table-column prop="errorCode" label="安全错误码" min-width="220"/><el-table-column label="操作" width="150"><template #default="{ row }"><el-button link type="primary" @click="run(() => show(row))">检查点与异常</el-button><el-button v-if="row.status === 'FAILED' && row.attempts < 5" link type="primary" @click="retry(row)">重试</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="prev, pager, next, total" @current-change="run(load)"/></section>
<el-drawer v-model="createOpen" title="建立 ERP 来源映射" size="520px"><p class="muted">使用现有主数据创建独立来源，不覆盖原档案。需先授予本账号公司级同步管理与供应商管理范围。</p><el-form label-position="top" @submit.prevent="create"><el-form-item label="适配器"><el-select v-model="form.adapterType" aria-label="适配器"><el-option label="Mock ERP" value="mock"/><el-option label="SAP OData（只读）" value="sap-odata" :disabled="!adapters.some(a => a.adapterType === 'sap-odata' && a.configured)"/></el-select></el-form-item><template v-if="form.adapterType === 'sap-odata'"><p class="muted">地址、CA 和凭据由部署私有配置管理。首次先验证元数据；业务同步还需配置准确的组织和订单白名单。</p><el-form-item label="来源系统标识"><el-input v-model="form.sourceSystem"/></el-form-item><el-form-item label="SAP Client"><el-input v-model="form.sourceClient"/></el-form-item><el-form-item label="外部公司代码"><el-input v-model="form.companyExternalKey"/></el-form-item><el-form-item label="外部采购组织"><el-input v-model="form.purchasingOrgExternalKey"/></el-form-item><el-form-item label="外部供应商编号"><el-input v-model="form.supplierExternalKey"/></el-form-item></template><el-form-item label="连接名称"><el-input v-model="form.name" aria-label="连接名称" maxlength="160"/></el-form-item><el-form-item label="公司"><el-select v-model="form.companyId" aria-label="映射公司" @change="form.plantIds = []; form.purchasingOrgId = ''; form.supplierId = ''"><el-option v-for="c in companies.filter(c => c.active)" :key="c.id" :label="c.name" :value="c.id"/></el-select></el-form-item><el-form-item label="采购组织"><el-select v-model="form.purchasingOrgId" aria-label="映射采购组织"><el-option v-for="o in orgs.filter(o => o.companyIds?.includes(form.companyId) && o.active)" :key="o.id" :label="o.name" :value="o.id"/></el-select></el-form-item><el-form-item label="供应商"><el-select v-model="form.supplierId" aria-label="映射供应商"><el-option v-for="s in suppliers.filter(s => s.companies?.some(c => c.companyId === form.companyId && c.active))" :key="s.id" :label="s.name" :value="s.id"/></el-select></el-form-item><el-form-item label="工厂（Mock 按选择顺序映射；SAP 填写外部代码）"><el-select v-model="form.plantIds" multiple aria-label="映射工厂"><el-option v-for="p in mappedPlants" :key="p.id" :label="p.name" :value="p.id"/></el-select></el-form-item><template v-if="form.adapterType === 'sap-odata'"><el-form-item v-for="id in form.plantIds" :key="id" :label="`${plants.find(p => p.id === id)?.name} 外部工厂代码`"><el-input v-model="externalPlants[id]" maxlength="40"/></el-form-item></template><el-button type="primary" native-type="submit">建立连接</el-button></el-form></el-drawer>
<el-drawer v-model="issuesOpen" title="同步检查点与隔离事件" size="75%"><template v-if="selected"><p>{{ states[selected.status] }} · 已处理 {{ selected.processed }} · 重试 {{ selected.attempts }}/5</p><p>同步读取批次：{{ selected.snapshotId }}；{{ selected.nextCursor ? '已保存分页检查点，可从此继续' : '当前没有后续页检查点' }}</p><el-table :data="issues" empty-text="本任务没有隔离事件"><el-table-column prop="externalKey" label="来源订单号"/><el-table-column prop="sourceRevision" label="来源版本"/><el-table-column prop="errorCode" label="安全错误码" min-width="300"/></el-table><el-pagination v-model:current-page="issuePage" :total="issueTotal" :page-size="20" layout="prev, pager, next, total" @current-change="run(issueList)"/></template></el-drawer>
</template><style scoped>.toolbar{display:flex;gap:12px;flex-wrap:wrap}.toolbar .el-select{width:230px}.el-select{width:100%}</style>

